        changes = 0
        left = 0
        right = len(sub_arr) - 1

        while left < right:
            if sub_arr[left] != sub_arr[right]:
                changes += 1
            left += 1
            right -= 1

        return changes

    middle_index = len(arr) // 2
    left_sub_arr = arr[:middle_index]
    right_sub_arr = arr[middle_index + len(arr) % 2:]

    if is_palindromic(arr):
        return 0

    return min_changes_to_palindrome(left_sub_arr) + min_changes_to_palindrome(right_sub_arr)

